"""Citation extraction and validation against retrieved policy evidence."""

import re
from typing import List, Set, Tuple

from app.schemas.explanation import ExplanationCitation
from app.schemas.policy_rag import PolicySearchResult


class CitationValidator:
    """Validates citations generated by LLM to eliminate hallucinated sources."""

    # Matches [DOC_ID:CHUNK_ID] or [CHUNK_ID]
    CITATION_PATTERN = re.compile(
        r"\[([A-Za-z0-9_\-\.]+)(?::([A-Za-z0-9_\-\.]+))?\]"
    )

    def extract_and_validate_citations(
        self,
        text: str,
        evidence: List[PolicySearchResult],
    ) -> List[ExplanationCitation]:
        """Extract citations from text and return only those matching retrieved policy evidence."""
        citations, _ = self.extract_and_filter_citations(text, evidence)
        return citations

    def extract_and_filter_citations(
        self,
        text: str,
        evidence: List[PolicySearchResult],
    ) -> Tuple[List[ExplanationCitation], List[str]]:
        """Extract citations from text, returning validated citations and warnings for rejected references."""
        chunk_map = {c.chunk_id: c for c in evidence}
        doc_map = {c.document_id: c for c in evidence}

        validated_citations: List[ExplanationCitation] = []
        cited_chunk_ids: Set[str] = set()
        warnings: List[str] = []

        matches = self.CITATION_PATTERN.findall(text)
        for part1, part2 in matches:
            ref_str = f"{part1}:{part2}" if part2 else part1
            matched_chunk = None

            if part2:
                # [DOC_ID:CHUNK_ID]
                if part2 in chunk_map:
                    matched_chunk = chunk_map[part2]
                elif part1 in chunk_map:
                    matched_chunk = chunk_map[part1]
            else:
                # [CHUNK_ID] or [DOC_ID]
                if part1 in chunk_map:
                    matched_chunk = chunk_map[part1]
                elif part1 in doc_map:
                    matched_chunk = doc_map[part1]

            if matched_chunk is not None:
                if matched_chunk.chunk_id not in cited_chunk_ids:
                    cited_chunk_ids.add(matched_chunk.chunk_id)
                    validated_citations.append(
                        ExplanationCitation(
                            chunk_id=matched_chunk.chunk_id,
                            document_id=matched_chunk.document_id,
                            policy_family_id=matched_chunk.policy_family_id,
                            document_title=matched_chunk.document_title,
                            version=matched_chunk.document_version,
                            section_title=matched_chunk.section_title,
                            excerpt=matched_chunk.content[:200],
                        )
                    )
            else:
                warnings.append(
                    f"Rejected invalid citation '{ref_str}': reference was not found in retrieved policy evidence."
                )

        return validated_citations, warnings

